"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.merging import merge_spans


def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def _between(start: int, end: int) -> List[Span]:
    return [Span(start, end)] if end > start else []


def _uncovered(merged: List[Span], opening: Span) -> List[Span]:
    gaps, cursor = [], opening.start
    for span in merged:
        gaps += _between(cursor, span.start)
        cursor = span.end
    return gaps + _between(cursor, opening.end)


def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    """Label each uncovered stretch, such as gap 12:00-13:00 (60 min).

    Raises ValueError when a worked span leaves opening hours.
    """
    merged = merge_spans(worked)
    for span in merged:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(f"outside opening hours: {span}")
    return [
        f"gap {_clock(g.start)}-{_clock(g.end)} ({g.minutes} min)"
        for g in _uncovered(merged, opening)
    ]

